async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { views: 1000, visitors: 500, bounceRate: 0.4 },
      notifications: [
        { id: 1, title: 'Welcome', message: 'Welcome to your dashboard' },
      ],
      settings: { theme: 'light', emailNotifications: true, language: 'en' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Views: {analytics.views}</p>
        <p>Visitors: {analytics.visitors}</p>
        <p>Bounce rate: {Math.round(analytics.bounceRate * 100)}%</p>
      </section>

      <section>
        <h3>Notifications</h3>
        <ul>
          {notifications.map((notification) => (
            <li key={notification.id}>
              <strong>{notification.title}</strong>: {notification.message}
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Email notifications: {settings.emailNotifications ? 'On' : 'Off'}</p>
        <p>Language: {settings.language}</p>
      </section>
    </div>
  )
}

